// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testRegression_property() public {
        c.initialize(address(0), address(0x1), 1000 ether, 100 ether, 100, 500, bytes32(0), false, false);
        uint256 fee = c.flashFee(address(0), 0);
        assertTrue(fee == 10**16, "flashFee should be _changeFee * 10^14");
    }
}
